\COPY db2_pdetcdcl (DCCCTR,DCCSUI,DCCUTI,DCCNLI,DCCSUC,DCCSSU,DCCNCL,DCCCLI,DCCART,DCCLIB,DCCQUC,DCCQUR,DCCQUL,DCCEXC,DCCAUT,DCCBSS,DCCBAA,DCCBSE,DCCLSS,DCCLAA,DCCLMM,DCCLJJ,DCCPAC,DCCPRV,DCCPVD,DCCPVN,DCCPVE,DCCTVA,DCCREM,DCCRES,DCCUNV,DCCGRO,DCCSGR,DCCCVV,DCCCAN,DCCCGR,DCCSTA,DCCSTB,DCCSTC,DCCSTD,DCCSTE,DCCSTF,DCCPSP,DCCNFA,DCCFSS,DCCFAA,DCCFMM,DCCFJJ,DCCCSS,DCCCAA,DCCCMM,DCCCJJ,DCCMSS,DCCMAA,DCCMMM,DCCMJJ,DCCLLL,DCCLOP,DCCARC,DCCRE) FROM '/opt/odoo/data/install/db2/pdetcdcl_2016-01_2018-03.csv' WITH DELIMITER AS ',' HEADER CSV QUOTE AS '"' ENCODING 'latin-1';

